# Break My Fix finding 1, generated by Tracefix: Language.fromietf raises ValueError.
# Property (issue): Same code gives equal languages
# Quote: I want to have true immutability of babelfish objects
# Run it with pytest: it fails for as long as the code breaks this property.

from babelfish.language import Language


def test_break_my_fix_1() -> None:
    ietf = 'script'
    result = Language.fromietf(ietf=ietf)
    result2 = Language.fromietf(**{'ietf': ietf, **({"ietf": ietf})})
    assert (result == result2 and str(result) == str(result2))
